#!/usr/bin/env python3
"""pokerogue_single.py - ONE file that builds a single-file, offline, no-audio PokeRogue.

Output: pokerogue.html (one self-contained HTML, ~100MB). Shiny/variant sprites are
flattened to one solid color. Needs: git, node >= 22, pnpm (corepack), python3 + Pillow.

  python3 pokerogue_single.py [--color f5c518] [--out pokerogue.html] [--work DIR]
                              [--dist PATH/TO/index.html]   (skip the Vite build, use this one)
Re-running resumes: the clone, the install and the flattened sprites are reused.
"""
import argparse, shutil, subprocess, sys, tempfile
from pathlib import Path

EMBEDDED = {'make_solid.py': '#!/usr/bin/env python3\n"""Flatten PokeRogue shiny + variant sprites to a single solid color.\n\nUsage: python3 make_solid.py <path/to/assets/images/pokemon> [--color f5c518]\n\nWhat it does (in place, so run it on a copy / build dir):\n  1. Every PNG under a \'shiny\' or \'variant\' folder becomes a flat silhouette of\n     itself: same size, same transparency, every visible pixel = one color.\n     The atlas .json files next to them stay valid because dimensions are unchanged.\n  2. Every variant palette map (variant/**/N.json) is rewritten so that EVERY\n     color in the matching base sprite maps to the same solid color, for all\n     variant tiers. Variants therefore render as the base sprite\'s silhouette\n     in that color instead of a recolor.\n"""\nimport json\nimport sys\nfrom pathlib import Path\n\nfrom PIL import Image\n\nargs = sys.argv[1:]\ncolor_hex = "f5c518"\nif "--color" in args:\n    i = args.index("--color")\n    color_hex = args[i + 1].lstrip("#").lower()\n    del args[i : i + 2]\nif len(args) != 1:\n    sys.exit(__doc__)\n\nroot = Path(args[0])\nif not root.is_dir():\n    sys.exit(f"not a directory: {root}")\n\nrgb = tuple(int(color_hex[i : i + 2], 16) for i in (0, 2, 4))\n\n\ndef is_target(p: Path) -> bool:\n    parts = p.relative_to(root).parts[:-1]\n    return "shiny" in parts or "variant" in parts\n\n\ndef flatten_png(p: Path) -> None:\n    im = Image.open(p).convert("RGBA")\n    alpha = im.getchannel("A")\n    out = Image.new("RGBA", im.size, rgb + (0,))\n    out.putalpha(alpha)\n    # fully transparent pixels: keep RGB uniform so PNG compresses to almost nothing\n    out.save(p, optimize=True)\n\n\ndef used_colors(p: Path) -> set[str]:\n    im = Image.open(p).convert("RGBA")\n    cols = set()\n    for count, (r, g, b, a) in im.getcolors(maxcolors=1 << 24) or []:\n        if a > 0:\n            cols.add(f"{r:02x}{g:02x}{b:02x}")\n    return cols\n\n\n# 1) PNGs\npng_count = 0\nbefore = after = 0\nfor p in root.rglob("*.png"):\n    if is_target(p):\n        before += p.stat().st_size\n        flatten_png(p)\n        after += p.stat().st_size\n        png_count += 1\n\n# 2) Variant palette maps\njson_count = 0\nfor j in root.rglob("*.json"):\n    rel = j.relative_to(root).parts\n    if "variant" not in rel[:-1]:\n        continue\n    # variant/back/12.json -> back/12.png ; variant/12.json -> 12.png\n    sub = [x for x in rel[:-1] if x != "variant"]\n    base_png = root.joinpath(*sub, j.stem + ".png")\n    try:\n        data = json.loads(j.read_text())\n    except Exception:\n        continue\n    if not isinstance(data, dict):\n        continue\n    base_colors = used_colors(base_png) if base_png.exists() else set()\n    for tier, mapping in list(data.items()):\n        if not isinstance(mapping, dict):\n            continue\n        keys = set(mapping.keys()) | base_colors\n        data[tier] = {k: color_hex for k in keys}\n    j.write_text(json.dumps(data, separators=(",", ":")))\n    json_count += 1\n\nprint(f"flattened {png_count} PNGs: {before/1e6:.1f}MB -> {after/1e6:.1f}MB")\nprint(f"rewrote {json_count} variant palette maps -> #{color_hex}")\n', 'pack.py': '#!/usr/bin/env python3\n"""Pack PokeRogue assets (no audio) into one gzip\'d blob + an offset index.\n\nUsage: python3 pack.py <repo_dir> <out_pack.gz> <out_index.json> [--pokemon-dir DIR]\n\n  repo_dir      checked-out pokerogue repo with the assets/ and locales/ submodules\n  --pokemon-dir use this (already flattened) copy instead of assets/images/pokemon\n\nJSON is minified, identical files are stored once, audio is skipped entirely.\nIndex format: { "images/pokemon/1.png": [offset, length], ... } (offsets are into\nthe *uncompressed* stream).\n"""\nimport gzip\nimport hashlib\nimport json\nimport sys\nfrom pathlib import Path\n\nargs = sys.argv[1:]\npokemon_dir = None\nif "--pokemon-dir" in args:\n    i = args.index("--pokemon-dir")\n    pokemon_dir = Path(args[i + 1])\n    del args[i : i + 2]\nif len(args) != 3:\n    sys.exit(__doc__)\n\nrepo, out_pack, out_index = Path(args[0]), Path(args[1]), Path(args[2])\nassets = repo / "assets"\nlocales = repo / "locales"\n\nSKIP_DIRS = {".git", "audio", "test", "node_modules"}\n\n\ndef walk(base: Path):\n    for p in sorted(base.rglob("*")):\n        if p.is_file() and not (set(p.relative_to(base).parts[:-1]) & SKIP_DIRS):\n            yield p\n\n\nentries = []  # (key, Path)\nfor sub in ("images", "battle-anims", "fonts"):\n    base = assets / sub\n    for p in walk(base):\n        if sub == "images" and pokemon_dir and p.is_relative_to(base / "pokemon"):\n            continue\n        entries.append((f"{sub}/{p.relative_to(base).as_posix()}", p))\nif pokemon_dir:\n    for p in walk(pokemon_dir):\n        entries.append((f"images/pokemon/{p.relative_to(pokemon_dir).as_posix()}", p))\nfor p in sorted(assets.glob("*.json")):\n    if p.name not in ("package.json", "tsconfig.json", "biome.jsonc"):\n        entries.append((p.name, p))\nfor p in walk(locales):\n    if p.suffix == ".json":\n        entries.append((f"locales/{p.relative_to(locales).as_posix()}", p))\n\nindex, seen = {}, {}\noffset = 0\nraw_total = 0\nwith gzip.open(out_pack, "wb", compresslevel=9) as gz:\n    for key, p in entries:\n        data = p.read_bytes()\n        raw_total += len(data)\n        if p.suffix == ".json":\n            try:\n                data = json.dumps(json.loads(data), separators=(",", ":"), ensure_ascii=False).encode()\n            except Exception:\n                pass\n        h = hashlib.sha1(data).digest()\n        if h in seen:\n            index[key] = seen[h]\n            continue\n        gz.write(data)\n        index[key] = seen[h] = [offset, len(data)]\n        offset += len(data)\n\nout_index.write_text(json.dumps(index, separators=(",", ":")))\nprint(f"{len(index)} files ({len(seen)} unique), source {raw_total/1e6:.0f}MB -> "\n      f"packed {offset/1e6:.0f}MB -> gzip {out_pack.stat().st_size/1e6:.0f}MB "\n      f"(~{out_pack.stat().st_size*1.34/1e6:.0f}MB as base64 in the HTML)")\n', 'assemble.py': '#!/usr/bin/env python3\n"""Combine Vite\'s single-file index.html + asset pack + shim into one HTML file.\n\nUsage: python3 assemble.py <dist/index.html> <pack.gz> <index.json> <shim.js> <out.html>\n"""\nimport base64\nimport re\nimport sys\nfrom pathlib import Path\n\nif len(sys.argv) != 6:\n    sys.exit(__doc__)\nhtml_p, pack_p, idx_p, shim_p, out_p = map(Path, sys.argv[1:])\n\nhtml = html_p.read_text(encoding="utf-8")\n\n# 1) move the game\'s inline module script into an inert <script> the shim starts later\nm = list(re.finditer(r"<script\\b[^>]*\\btype=\\"module\\"[^>]*>", html))\nif len(m) != 1:\n    sys.exit(f"expected exactly 1 inline module script, found {len(m)} "\n             "(is vite-plugin-singlefile active?)")\nstart = m[0].end()\nend = html.index("</script>", start)\ngame_code = html[start:end]\nif not game_code.strip():\n    sys.exit("module script is empty - it was not inlined; check the single-file build")\nhtml = html[: m[0].start()] + \'<script type="text/plain" id="pr-game">\' + game_code + "</script>" + html[end + len("</script>"):]\n\n# 2) shim goes first in <head>\nshim = shim_p.read_text(encoding="utf-8")\nhm = re.search(r"<head[^>]*>", html)\nif not hm:\n    sys.exit("no <head> found")\nhtml = html[: hm.end()] + "<script>" + shim + "</script>" + html[hm.end():]\n\n# 3) pack + index just before </body>\nb64 = base64.b64encode(pack_p.read_bytes()).decode("ascii")\nidx = idx_p.read_text()\ntail = (\'<script type="application/json" id="pr-index">\' + idx + "</script>"\n        \'<script type="text/plain" id="pr-pack">\' + b64 + "</script>")\nbi = html.rindex("</body>")\nhtml = html[:bi] + tail + html[bi:]\n\nout_p.write_text(html, encoding="utf-8")\nprint(f"wrote {out_p} ({out_p.stat().st_size/1e6:.0f}MB)")\n', 'shim.js': '/* PokeRogue single-file runtime shim.\n * Runs before the game. Decodes the embedded asset pack into an in-memory Blob,\n * redirects asset requests (fetch / XHR / <img> / <video> / FontFace) to blob: URLs,\n * answers audio requests with silence, then starts the game code. */\n(function () {\n  "use strict";\n  var IDX = null, PACK = null, URLS = Object.create(null);\n  var MIME = { json: "application/json", png: "image/png", ttf: "font/ttf", otf: "font/otf",\n    mp4: "video/mp4", webp: "image/webp", jpg: "image/jpeg", jpeg: "image/jpeg",\n    gif: "image/gif", svg: "image/svg+xml", txt: "text/plain" };\n\n  function mkBlobUrl(parts, type) { return URL.createObjectURL(new Blob(parts, { type: type })); }\n\n  // 0.1s of 8kHz mono 16-bit silence, so audio decoding succeeds without real audio.\n  var SILENCE = (function () {\n    var n = 800, b = new ArrayBuffer(44 + n * 2), v = new DataView(b);\n    function s(o, t) { for (var i = 0; i < t.length; i++) v.setUint8(o + i, t.charCodeAt(i)); }\n    s(0, "RIFF"); v.setUint32(4, 36 + n * 2, true); s(8, "WAVE"); s(12, "fmt ");\n    v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);\n    v.setUint32(24, 8000, true); v.setUint32(28, 16000, true); v.setUint16(32, 2, true);\n    v.setUint16(34, 16, true); s(36, "data"); v.setUint32(40, n * 2, true);\n    return mkBlobUrl([b], "audio/wav");\n  })();\n  var EMPTY_JSON = mkBlobUrl(["{}"], "application/json");\n\n  var ROOT_RE = /(?:^|\\/)((?:images|battle-anims|fonts|locales|audio)\\/[^?#]*|manifest\\.json)(?:[?#].*)?$/;\n  function norm(u) {\n    try { u = String(u); } catch (e) { return null; }\n    if (u.indexOf("blob:") === 0 || u.indexOf("data:") === 0) return null;\n    var m = ROOT_RE.exec(u);\n    if (m) { try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; } }\n    var b = /([^\\/?#]+\\.json)(?:[?#].*)?$/.exec(u); // root-level json such as exp-sprites.json\n    return b && IDX && IDX[b[1]] ? b[1] : null;\n  }\n  function lookup(u) {\n    if (u == null) return u;\n    var k = norm(u);\n    if (!k) return u;\n    if (k.indexOf("audio/") === 0) return SILENCE;\n    if (k === "manifest.json") return EMPTY_JSON;\n    if (!IDX || !IDX[k]) { console.warn("[single-file] asset not in pack:", k); return u; }\n    if (!URLS[k]) {\n      var e = IDX[k], ext = k.slice(k.lastIndexOf(".") + 1).toLowerCase();\n      URLS[k] = URL.createObjectURL(PACK.slice(e[0], e[0] + e[1], MIME[ext] || "application/octet-stream"));\n    }\n    return URLS[k];\n  }\n\n  // fetch\n  var ofetch = window.fetch;\n  window.fetch = function (input, init) {\n    var u = typeof input === "string" || input instanceof URL ? String(input) : input && input.url;\n    var r = lookup(u);\n    return ofetch.call(this, r !== u ? r : input, init);\n  };\n  // XMLHttpRequest (Phaser\'s loader)\n  var oopen = XMLHttpRequest.prototype.open;\n  XMLHttpRequest.prototype.open = function (method, url) {\n    var a = Array.prototype.slice.call(arguments);\n    a[1] = lookup(url);\n    return oopen.apply(this, a);\n  };\n  // <img>, <video>, <audio> .src\n  [HTMLImageElement, HTMLMediaElement].forEach(function (C) {\n    var d = Object.getOwnPropertyDescriptor(C.prototype, "src");\n    if (!d || !d.set) return;\n    Object.defineProperty(C.prototype, "src", {\n      configurable: true, enumerable: d.enumerable, get: d.get,\n      set: function (v) { d.set.call(this, lookup(v)); }\n    });\n  });\n  // FontFace url(...)\n  var OFF = window.FontFace;\n  if (OFF) {\n    window.FontFace = function (family, source, desc) {\n      if (typeof source === "string") {\n        source = source.replace(/url\\(\\s*([\'"]?)([^\'")]+)\\1\\s*\\)/g, function (m, q, u) {\n          return \'url("\' + lookup(u) + \'")\';\n        });\n      }\n      return new OFF(family, source, desc);\n    };\n    window.FontFace.prototype = OFF.prototype;\n  }\n\n  function overlay(text) {\n    var d = document.getElementById("pr-loading");\n    if (!d) {\n      d = document.createElement("div"); d.id = "pr-loading";\n      d.style.cssText = "position:fixed;inset:0;display:flex;align-items:center;justify-content:center;" +\n        "background:#111;color:#eee;font:16px sans-serif;z-index:99999;text-align:center;padding:24px";\n      document.body.appendChild(d);\n    }\n    d.textContent = text;\n    return d;\n  }\n\n  async function boot() {\n    try {\n      var ov = overlay("Unpacking game data (one-time per launch, can take a while)…");\n      IDX = JSON.parse(document.getElementById("pr-index").textContent);\n      var el = document.getElementById("pr-pack");\n      var b64 = el.textContent.trim(), parts = [], STEP = 4 * 1024 * 1024; // multiple of 4\n      for (var i = 0; i < b64.length; i += STEP) {\n        var bin = atob(b64.substr(i, STEP)), u8 = new Uint8Array(bin.length);\n        for (var j = 0; j < bin.length; j++) u8[j] = bin.charCodeAt(j);\n        parts.push(u8);\n      }\n      el.textContent = ""; b64 = null;                       // free the big string\n      var gz = new Blob(parts); parts = null;\n      PACK = await new Response(gz.stream().pipeThrough(new DecompressionStream("gzip"))).blob();\n      var code = document.getElementById("pr-game").textContent;\n      var s = document.createElement("script");\n      s.type = "module"; s.textContent = code;\n      document.body.appendChild(s);\n      ov.remove();\n    } catch (e) {\n      overlay("Failed to start: " + (e && e.message ? e.message : e));\n      console.error(e);\n    }\n  }\n  window.__prShimLookup = lookup; // handy for debugging\n  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot);\n  else boot();\n})();\n', 'vite.single.config.ts': '// Copied into the pokerogue repo by build.sh. Wraps the project\'s own config and\n// inlines all JS/CSS into index.html. Assets are NOT bundled by Vite (the repo builds\n// with publicDir: false); pack.py + shim.js supply them instead.\nimport { defineConfig, mergeConfig } from "vite";\nimport { viteSingleFile } from "vite-plugin-singlefile";\nimport baseConfig from "./vite.config";\n\nexport default defineConfig(async env => {\n  const base = await (baseConfig as any)(env);\n  return mergeConfig(base, {\n    plugins: [viteSingleFile()],\n    build: {\n      sourcemap: false,\n      assetsInlineLimit: 100_000_000,\n      cssCodeSplit: false,\n    },\n  });\n});\n'}

def run(cmd, cwd=None):
    print("+", " ".join(map(str, cmd)), flush=True)
    subprocess.run(list(map(str, cmd)), cwd=cwd, check=True)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--color", default="f5c518")
    ap.add_argument("--out", default="pokerogue.html")
    ap.add_argument("--work", default="pokerogue-work")
    ap.add_argument("--dist", default=None)
    a = ap.parse_args()
    out, work = Path(a.out).resolve(), Path(a.work).resolve()
    work.mkdir(parents=True, exist_ok=True)
    tools = work / "_tools"
    tools.mkdir(exist_ok=True)
    for name, text in EMBEDDED.items():
        (tools / name).write_text(text, encoding="utf-8")
    repo = work / "pokerogue"
    if not (repo / ".git").exists():
        run(["git", "clone", "--depth", "1", "--recurse-submodules", "--shallow-submodules",
             "https://github.com/pagefaultgames/pokerogue.git", repo])
    if a.dist:
        dist_html = Path(a.dist).resolve()
    else:
        run(["corepack", "enable"]) if shutil.which("corepack") else None
        run(["pnpm", "install"], cwd=repo)
        run(["pnpm", "add", "-D", "vite-plugin-singlefile"], cwd=repo)
        shutil.copy(tools / "vite.single.config.ts", repo / "vite.single.config.ts")
        run(["pnpm", "exec", "vite", "build", "--mode", "app", "-c", "vite.single.config.ts"], cwd=repo)
        dist_html = repo / "dist" / "index.html"
    pk = work / "pokemon"
    marker = pk / (".flattened-" + a.color.lstrip("#").lower())
    if not marker.exists():
        shutil.rmtree(pk, ignore_errors=True)
        shutil.copytree(repo / "assets" / "images" / "pokemon", pk)
        run([sys.executable, "-I", tools / "make_solid.py", pk, "--color", a.color])
        marker.write_text("ok")
    run([sys.executable, "-I", tools / "pack.py", repo, work / "pack.gz", work / "index.json", "--pokemon-dir", pk])
    run([sys.executable, "-I", tools / "assemble.py", dist_html, work / "pack.gz", work / "index.json", tools / "shim.js", out])
    print("Done:", out)

if __name__ == "__main__":
    main()
